import java.util.*;

class Solution {
    public int secludedTown(int n, int[][] roads, int limit) {
        final int INF = 1_000_000_000; // safe to add two without overflow
        int[][] d = new int[n][n];
        for (int i = 0; i < n; i++) { Arrays.fill(d[i], INF); d[i][i] = 0; }
        for (int[] e : roads) {
            d[e[0]][e[1]] = Math.min(d[e[0]][e[1]], e[2]);
            d[e[1]][e[0]] = Math.min(d[e[1]][e[0]], e[2]);
        }
        for (int m = 0; m < n; m++) // allow town m as a middle stop
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++)
                    if (d[i][m] + d[m][j] < d[i][j]) d[i][j] = d[i][m] + d[m][j];
        int best = -1, bestCount = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            int cnt = 0;
            for (int j = 0; j < n; j++) if (j != i && d[i][j] <= limit) cnt++;
            if (cnt <= bestCount) { bestCount = cnt; best = i; } // <= : larger town wins ties
        }
        return best;
    }
}

