class Solution:
    def secludedTown(self, n: int, roads: List[List[int]], limit: int) -> int:
        d = [[inf] * n for _ in range(n)]
        for i in range(n): d[i][i] = 0
        for a, b, w in roads:
            d[a][b] = min(d[a][b], w); d[b][a] = min(d[b][a], w)
        for k in range(n):
            dk = d[k]
            for i in range(n):
                dik = d[i][k]
                if dik == inf: continue
                di = d[i]
                for j in range(n):
                    if dik + dk[j] < di[j]: di[j] = dik + dk[j]
        best, ans = inf, -1
        for i in range(n):
            cnt = sum(1 for j in range(n) if j != i and d[i][j] <= limit)
            if cnt <= best: best, ans = cnt, i
        return ans

