function secludedTown(n, roads, limit) {
  const g = Array.from({length: n}, () => []);
  for (const [a, b, w] of roads) { g[a].push([b, w]); g[b].push([a, w]); }
  let best = Infinity, ans = -1;
  for (let s = 0; s < n; s++) {
    const d = new Array(n).fill(Infinity), done = new Array(n).fill(false); d[s] = 0;
    for (let it = 0; it < n; it++) {
      let v = -1; for (let i = 0; i < n; i++) if (!done[i] && (v < 0 || d[i] < d[v])) v = i;
      if (d[v] === Infinity) break; done[v] = true;
      for (const [u, w] of g[v]) if (d[v] + w < d[u]) d[u] = d[v] + w;
    }
    let cnt = 0; for (let j = 0; j < n; j++) if (j !== s && d[j] <= limit) cnt++;
    if (cnt <= best) { best = cnt; ans = s; }
  }
  return ans;
}
